/**
 * Generates design token artifacts from `src/tokens/primitive.json` and `src/tokens/semantic.json`.
 *
 * Outputs (all in `src/tokens/`, do not edit by hand):
 * - `tokens.css`  primitive tokens as a Tailwind `@theme static` block
 * - `themes.css`  semantic tokens resolved with `light-dark()` per theme
 * - `index.ts`    `designTokens` constant with colors as deck.gl RGBA tuples (0-255)
 * - `types.ts`    TypeScript types derived from the token JSON
 */
import { readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const TOKENS_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'src', 'tokens')
const HEADER = '/* Generated by scripts/generate-tokens.mjs. Do not edit by hand. */'

//#region Color conversion
const HEX_RE = /^#(?:[\da-f]{3,4}|[\da-f]{6}|[\da-f]{8})$/i
const RGBA_RE = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/i

/** @param {string} value */
export function isColor(value) {
  return HEX_RE.test(value) || RGBA_RE.test(value)
}

/**
 * Converts a hex or rgb(a) CSS color to a deck.gl RGBA tuple with every channel in 0-255.
 * @param {string} value
 * @returns {[number, number, number, number]}
 */
export function toRgba255(value) {
  if (HEX_RE.test(value)) {
    let hex = value.slice(1)
    if (hex.length <= 4) hex = [...hex].map((c) => c + c).join('')
    const channels = hex.match(/../g).map((pair) => Number.parseInt(pair, 16))
    return /** @type {[number, number, number, number]} */ ([
      ...channels.slice(0, 3),
      channels[3] ?? 255,
    ])
  }

  const match = value.match(RGBA_RE)
  if (!match) throw new Error(`Unsupported color value: ${value}`)

  const [, r, g, b, a = '1'] = match
  const alpha = a.endsWith('%') ? Number.parseFloat(a) / 100 : Number.parseFloat(a)
  return [Number(r), Number(g), Number(b), Math.round(alpha * 255)]
}
//#endregion

//#region Token utils
/**
 * Flattens nested token objects into `{ 'a-b-c': value }`.
 * @param {Record<string, unknown>} obj
 * @param {string} [prefix]
 * @returns {Record<string, string | number>}
 */
export function flattenTokens(obj, prefix = '') {
  /** @type {Record<string, string | number>} */
  const result = {}

  for (const [key, value] of Object.entries(obj)) {
    const name = prefix ? `${prefix}-${key}` : key
    if (value !== null && typeof value === 'object') {
      Object.assign(result, flattenTokens(/** @type {Record<string, unknown>} */ (value), name))
    } else {
      result[name] = /** @type {string | number} */ (value)
    }
  }

  return result
}

/**
 * Resolves a `--primitive-*` style reference to its raw primitive value.
 * @param {string} ref
 * @param {Record<string, string | number>} primitives
 */
function resolveRef(ref, primitives) {
  const value = primitives[ref.replace(/^--/, '')]
  if (value === undefined)
    throw new Error(`Token reference ${ref} does not match a primitive token`)
  return value
}
//#endregion

//#region CSS generation
/** @param {Record<string, string | number>} primitives */
export function generatePrimitivesCss(primitives) {
  const lines = Object.entries(primitives).map(
    ([key, value]) => `  --${key.replace(/-base$/, '')}: ${value};`,
  )
  return `${HEADER}\n\n@theme static {\n${lines.join('\n')}\n}\n`
}

const SHADOW_RE = /^(?<offsets>(?:[\d.]+(?:px|rem|em)?\s+){3,4})\s*(?<color>rgba?\([^)]+\))$/

/**
 * `light-dark()` only accepts `<color>` values, so shadow tokens share their offsets and switch
 * only the color. Returns `null` when the shadows can't be expressed that way.
 * @param {string} varName
 * @param {string} light
 * @param {string} dark
 */
function shadowDeclaration(varName, light, dark) {
  const l = String(light).trim().match(SHADOW_RE)?.groups
  const d = String(dark).trim().match(SHADOW_RE)?.groups
  if (!l || !d || l.offsets.trim() !== d.offsets.trim()) return null
  return `--${varName}: ${l.offsets.trim()} light-dark(${l.color}, ${d.color});`
}

/**
 * @param {Record<string, unknown>} lightObj
 * @param {Record<string, unknown>} darkObj
 * @param {Record<string, string | number>} primitives
 * @param {string} prefix
 * @returns {string[]}
 */
function semanticDeclarations(lightObj, darkObj, primitives, prefix = '') {
  /** @type {string[]} */
  const lines = []

  for (const [key, lightValue] of Object.entries(lightObj)) {
    const darkValue = darkObj?.[key]
    const varName = key === 'base' ? prefix : prefix ? `${prefix}-${key}` : key

    if (typeof lightValue === 'string' && lightValue.startsWith('--')) {
      if (typeof darkValue !== 'string') {
        throw new Error(`Semantic token "${varName}" is missing from the dark theme`)
      }
      const lightFallback = resolveRef(lightValue, primitives)
      const darkFallback = resolveRef(darkValue, primitives)

      const shadow = varName.includes('shadow')
        ? shadowDeclaration(varName, String(lightFallback), String(darkFallback))
        : null

      lines.push(
        shadow ??
          `--${varName}: light-dark(var(${lightValue}, ${lightFallback}), var(${darkValue}, ${darkFallback}));`,
      )
    } else if (lightValue !== null && typeof lightValue === 'object') {
      lines.push(
        ...semanticDeclarations(
          /** @type {Record<string, unknown>} */ (lightValue),
          /** @type {Record<string, unknown>} */ (darkValue),
          primitives,
          varName,
        ),
      )
    }
  }

  return lines
}

/**
 * @param {{ light: Record<string, unknown>, dark: Record<string, unknown> }} semantic
 * @param {Record<string, string | number>} primitives
 */
export function generateThemesCss(semantic, primitives) {
  const lines = semanticDeclarations(semantic.light, semantic.dark, primitives)
  return `${HEADER}\n\n@import './tokens.css';\n\n@theme static {\n${lines.map((l) => `  ${l}`).join('\n')}\n}\n`
}
//#endregion

//#region TypeScript generation
/**
 * Converts token values for JS consumers: colors become RGBA tuples, `px` values become numbers.
 * @param {unknown} value
 * @param {Record<string, string | number>} primitives
 * @returns {unknown}
 */
export function toJsTokens(value, primitives) {
  if (typeof value === 'string') {
    const raw = value.startsWith('--') ? resolveRef(value, primitives) : value
    if (typeof raw === 'number') return raw
    if (/^-?[\d.]+px$/.test(raw)) return Number.parseFloat(raw)
    if (isColor(raw)) return toRgba255(raw)
    return raw
  }

  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([key, child]) => [key, toJsTokens(child, primitives)]),
    )
  }

  return value
}

/** @param {string} key */
function propertyKey(key) {
  return /^[A-Za-z_$][\w$]*$/.test(key) ? key : `'${key}'`
}

/**
 * Builds a TypeScript type literal from a converted token object.
 * @param {unknown} value
 * @param {number} depth
 * @returns {string}
 */
function typeLiteral(value, depth = 0) {
  if (Array.isArray(value)) return 'RGBA'
  if (typeof value === 'number') return 'number'
  if (typeof value === 'string') return 'string'

  const pad = '  '.repeat(depth + 1)
  const entries = Object.entries(/** @type {Record<string, unknown>} */ (value)).map(
    ([key, child]) => `${pad}${propertyKey(key)}: ${typeLiteral(child, depth + 1)};`,
  )
  return `{\n${entries.join('\n')}\n${'  '.repeat(depth)}}`
}

/**
 * @param {Record<string, any>} tokens converted tokens, as returned by `toJsTokens`
 */
export function generateTypes(tokens) {
  const { dark, primitive, domain, typography, ...rest } = tokens

  const themeEntries = [
    '  dark: SemanticColorTokens;',
    '  light: SemanticColorTokens;',
    '  primitive: PrimitiveColorTokens;',
    '  domain: DomainColorTokens;',
    `  typography: {\n${Object.keys(typography)
      .map((key) => `    ${key}: TypographyTokenSet;`)
      .join('\n')}\n  };`,
    ...Object.entries(rest)
      .filter(([key]) => key !== 'light')
      .map(([key, value]) => `  ${propertyKey(key)}: ${typeLiteral(value, 1)};`),
  ]

  return `${HEADER}

/** Color as a deck.gl RGBA tuple, every channel 0-255 */
export type RGBA = [number, number, number, number];

/** Primitive color tokens which feed into semantic color tokens */
export type PrimitiveColorTokens = ${typeLiteral(primitive)};

/** Domain specific color tokens */
export type DomainColorTokens = ${typeLiteral(domain)};

/** Semantic color tokens, identical in shape for the light and dark themes */
export type SemanticColorTokens = ${typeLiteral(dark)};

export type TypographyTokenSet = ${typeLiteral(typography.height)};

/** Complete theme token structure including colors, typography, spacing, radius, and shadows */
export type ThemeTokens = {
${themeEntries.join('\n')}
};
`
}

/** @param {unknown} tokens */
export function generateIndex(tokens) {
  return `${HEADER}

import type { ThemeTokens } from './types.js';

export type * from './types.js';

export const designTokens = ${JSON.stringify(tokens, null, 2)} satisfies ThemeTokens;
`
}
//#endregion

/** @param {string} file */
function readJson(file) {
  return JSON.parse(readFileSync(path.join(TOKENS_DIR, file), 'utf-8'))
}

/** @param {string} file @param {string} content */
function write(file, content) {
  writeFileSync(path.join(TOKENS_DIR, file), content, 'utf-8')
}

export function main() {
  const primitiveConfig = readJson('primitive.json')
  const semanticConfig = readJson('semantic.json')
  const primitives = flattenTokens(primitiveConfig)

  write('tokens.css', generatePrimitivesCss(primitives))
  write('themes.css', generateThemesCss(semanticConfig, primitives))

  // Fonts and icon sizes are CSS-only concerns and are not exported to JS.
  const { font: _font, icon: _icon, ...jsPrimitives } = primitiveConfig
  const jsTokens = {
    .../** @type {object} */ (toJsTokens(semanticConfig, primitives)),
    .../** @type {object} */ (toJsTokens(jsPrimitives, primitives)),
  }

  write('types.ts', generateTypes(jsTokens))
  write('index.ts', generateIndex(jsTokens))

  console.log('Generated tokens.css, themes.css, types.ts and index.ts')
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main()
}
